    'Site Title' => 'Կայքին խորագիրը',
    'Site Description (shown in Google results)' => 'Կայքին նկարագրութիւնը (կը ցուցադրուի Google-ի արդիւնքներուն մէջ)',
    'Site Owner (Name / Studio)' => 'Կայքին տէրը (անուն / տաղաւար)',
    'Used in the copyright notice, Google structured data, legal notice, feed author and admin header.' => 'Կը գործածուի հեղինակային իրաւունքի նշումին, Google-ի կառուցուածքային տուեալներուն, իրաւական ծանուցումին մէջ, որպէս լրահոսի հեղինակ եւ վարիչի էջագլուխին մէջ։',
    'Contact Email' => 'Կապի ել-նամակ',
    'Contact form notifications are sent to this address.' => 'Կապի ձեւաթուղթի ծանուցումները կ՚ուղարկուին այս հասցէին։',
    'Phone' => 'Հեռաձայն',
    'Hidden on the Contact page when empty.' => 'Պարապ ըլլալու պարագային կը պահուի Կապ էջին մէջ։',
    'Enter the addresses here. Choose whether icons appear in the header or footer under Themes › Customise › Menu / Footer.' => 'Մուտքագրեցէք հասցէները հոս։ Պատկերակներուն էջագլուխին կամ էջատակին մէջ երեւիլը ընտրեցէք Կաղապարներ › Յարմարեցնել › Մենիւ / Էջատակ բաժինէն։',
    'Visibility:' => 'Տեսանելիութիւն՝',
    'Address (e.g. /en/map/ or https://…)' => 'Հասցէ (օր.՝ /en/map/ կամ https://…)',
    'Address' => 'Հասցէ',
    'Remove link' => 'Հեռացնել յղումը',
    'Extra footer links' => 'Էջատակի յաւելեալ յղումներ',
    'Links shown only in the footer strip (e.g. imprint, press kit). The main menu is edited on the Pages screen; the footer design under Themes › Customise › Footer.' => 'Յղումներ, որոնք կը ցուցադրուին միայն էջատակի շերտին մէջ (օր.՝ ելքային տուեալներ, մամուլի ծրար)։ Գլխաւոր մենիւն կը խմբագրուի Էջեր պաստառին մէջ, էջատակի ձեւաւորումը՝ Կաղապարներ › Յարմարեցնել › Էջատակ բաժինին մէջ։',
    'Add link' => 'Աւելցնել յղում',
