    'Show the announcement bar' => 'Ցուցադրել յայտարարութեան տողը',
    'Announcement text' => 'Յայտարարութեան բնագիր',
    'e.g. New exhibition: Walls and Faces · 12 December, Istanbul' => 'օր.՝ Նոր ցուցահանդէս. Պատեր եւ դէմքեր · դեկտեմբեր 12, Պոլիս',
    'Link (optional)' => 'Յղում (ըստ ընտրութեան)',
