    'When on, visitors see the notice below instead of the site. As an admin you still see the site normally.' => 'Միացուած ըլլալու պարագային այցելուները կայքին փոխարէն կը տեսնեն ստորեւ բերուած ծանուցումը։ Որպէս վարիչ՝ դուք կը շարունակէք կայքը տեսնել սովորական կերպով։',
    'Logo, Emblem & Favicon Files' => 'Լոկօի, զինանշանի եւ favicon-ի ֆայլեր',
