    'Upload logo files here. To choose how the logo appears in the header (emblem, full logo, name only, size):' => 'Վերբեռնեցէք լոկօի ֆայլերը հոս։ Ընտրելու համար, թէ ինչպէս լոկօն կ՚երեւի էջագլուխին մէջ (զինանշան, ամբողջական լոկօ, միայն անուն, չափ)՝',
    'Header › Logo' => 'Էջագլուխ › Լոկօ',
