    'Articles, field notes and news' => 'Յօդուածներ, դաշտային նշումներ եւ լուրեր',
    'Manage posts' => 'Կառավարել գրառումները',
    'Edit design' => 'Խմբագրել ձեւաւորումը',
    'Contact form and details' => 'Կապի ձեւաթուղթ եւ տուեալներ',
