    'Right-Click & Drag Protection' => 'Աջ սեղմումէն եւ քաշելէն պաշտպանութիւն',
    'Blocks right-click saving and dragging of photos and shows a copyright (©) notice.' => 'Կ՚արգիլէ լուսանկարներու պահումը աջ սեղմումով եւ անոնց քաշելը, ու կը ցուցադրէ հեղինակային իրաւունքի (©) ծանուցում։',
    'Fullscreen Viewer (Lightbox)' => 'Ամբողջ պաստառով դիտիչ (Lightbox)',
    'When off, clicking a photo does not open a large view.' => 'Անջատուած ըլլալու պարագային լուսանկարին վրայ սեղմելը մեծ տեսք չի բանար։',
    'Buttons Shown in the Viewer' => 'Դիտիչին մէջ ցուցադրուող կոճակներ',
    'Photo counter (01 / 18)' => 'Լուսանկարներու հաշուիչ (01 / 18)',
    'Slideshow (play / pause)' => 'Սահիկներու ցուցադրութիւն (նուագել / դադար)',
