    'Fullscreen button' => 'Ամբողջ պաստառի կոճակ',
    'Camera & EXIF info' => 'Խցիկի եւ EXIF տուեալներ',
    'To change page layouts, colors, header and footer design:' => 'Էջերու դասաւորութիւնները, գոյները, էջագլուխի եւ էջատակի ձեւաւորումը փոխելու համար՝',
    'Privacy Notice and Explicit Consent pages. When on, links appear in the footer.' => 'Գաղտնիութեան ծանուցման եւ Յստակ համաձայնութեան էջեր։ Միացուած ըլլալու պարագային յղումները կը յայտնուին էջատակին մէջ։',
