    '"Manage Preferences" Button' => '«Կառավարել նախընտրութիւնները» կոճակ',
    '"Save Preferences" Button' => '«Պահել նախընտրութիւնները» կոճակ',
    'Necessary Cookies Title' => 'Անհրաժեշտ թխուածքաբլիթներու խորագիր',
    'Necessary Cookies Description' => 'Անհրաժեշտ թխուածքաբլիթներու նկարագրութիւն',
    '"Always active" Label' => '«Միշտ գործօն» պիտակ',
    'Analytics Cookies Title' => 'Վերլուծական թխուածքաբլիթներու խորագիր',
    'Analytics Cookies Description' => 'Վերլուծական թխուածքաբլիթներու նկարագրութիւն',
    'Policy Link Text' => 'Քաղաքականութեան յղումի բնագիր',
    'Cookie Consent (KVKK / GDPR)' => 'Թխուածքաբլիթներու համաձայնութիւն (KVKK / GDPR)',
    'Shows a banner asking visitors for their cookie choice on first visit. Works in all active languages.' => 'Առաջին այցելութեան ատեն կը ցուցադրէ ազդագօտի մը, որ կը հարցնէ այցելուներուն թխուածքաբլիթներու ընտրութիւնը։ Կ՚աշխատի բոլոր գործօն լեզուներով։',
    'Cookie Consent Banner' => 'Թխուածքաբլիթներու համաձայնութեան ազդագօտի',
    'When on, Google Analytics loads only after the visitor consents.' => 'Միացուած ըլլալու պարագային Google Analytics-ը կը բեռնուի միայն այցելուին համաձայնութենէն ետք։',
    'Layout' => 'Դասաւորութիւն',
    'Box in bottom-left corner' => 'Տուփ վարի ձախ անկիւնը',
    'Full-width bar at the bottom' => 'Ամբողջ լայնքով տող վարը',
    'How it works' => 'Ինչպէս կ՚աշխատի',
    '• "Accept" and "Reject" have equal weight; the analytics switch is off by default (KVKK Cookie Guide / GDPR).' => '• «Ընդունիլ» եւ «Մերժել» կոճակները հաւասարազօր են. վերլուծութեան անջատիչը նախնականօրէն անջատուած է (KVKK թխուածքաբլիթներու ուղեցոյց / GDPR)։',
    '• The visitor\'s choice is kept for 180 days and can be changed anytime via the "Cookie Preferences" footer link.' => '• Այցելուին ընտրութիւնը կը պահուի 180 օր եւ որեւէ պահու կրնայ փոխուիլ էջատակի «Թխուածքաբլիթներու նախընտրութիւններ» յղումով։',
    '• Google Analytics: ' => '• Google Analytics՝ ',
    'not set' => 'սահմանուած չէ',
    'Consent version: ' => 'Համաձայնութեան տարբերակ՝ ',
    '• Empty text fields use the built-in translation for each language.' => '• Պարապ բնագրային դաշտերը կը գործածեն իւրաքանչիւր լեզուի ներկառուցուած թարգմանութիւնը։',
    'Banner Texts' => 'Ազդագօտիի բնագիրներ',
    'Policy Link (defaults to Privacy Notice page)' => 'Քաղաքականութեան յղում (նախնականը՝ Գաղտնիութեան ծանուցման էջը)',
    'If you changed the texts or how cookies are used, you can show the banner again to visitors who already decided.' => 'Եթէ փոխած էք բնագիրները կամ թխուածքաբլիթներու գործածութեան ձեւը, կրնաք ազդագօտին կրկին ցուցադրել այն այցելուներուն, որոնք արդէն որոշում տուած են։',
    'Show the cookie banner to all visitors again?' => 'Կրկին ցուցադրե՞լ թխուածքաբլիթներու ազդագօտին բոլոր այցելուներուն',
    'Show again' => 'Ցուցադրել կրկին',
    'Ask Everyone Again' => 'Կրկին հարցնել բոլորին',
    'Google Services' => 'Google ծառայութիւններ',
    'Keys used for visitor statistics and maps. Leave them as they are if unsure.' => 'Այցելուներու վիճակագրութեան եւ քարտէզներու համար գործածուող բանալիներ։ Եթէ վստահ չէք, ձգեցէք ինչպէս որ են։',
    'Google Analytics Measurement ID' => 'Google Analytics չափման ID',
    'Adds visitor tracking. If cookie consent is on, it only runs for visitors who accept.' => 'Կ՚աւելցնէ այցելուներու հետագծում։ Եթէ թխուածքաբլիթներու համաձայնութիւնը միացուած է, ան կ՚աշխատի միայն համաձայնած այցելուներուն համար։',
    'Statistics Connection (GA4 Property ID & Service Account)' => 'Վիճակագրութեան կապ (GA4 Property ID եւ ծառայողական հաշիւ)',
    'Lets the Statistics page fetch data from Google. Set up there, with a connection test and JSON file upload.' => 'Կը թոյլատրէ Վիճակագրութիւն էջին տուեալներ ստանալ Google-էն։ Կը կարգաւորուի հոն՝ կապի ստուգումով եւ JSON ֆայլի վերբեռնումով։',
    'Connection Settings' => 'Կապի կարգաւորումներ',
    'For the map on the contact page.' => 'Կապի էջի քարտէզին համար։',
    'Image Converter (AVIF / WebP)' => 'Պատկերներու փոխարկիչ (AVIF / WebP)',
    'Generates next-gen AVIF/WebP formats and responsive thumbnails.' => 'Կը ստեղծէ նոր սերունդի AVIF/WebP ձեւաչափեր եւ յարմարուող մանրապատկերներ։',
    'Open Converter →' => 'Բանալ փոխարկիչը →',
    'Panel language and site languages:' => 'Վահանակին լեզուն եւ կայքին լեզուները՝',
    'Cinematic Dark' => 'Շարժանկարային մութ',
    'Most Popular' => 'Ամենատարածուածը',
    'Deep black darkroom ambience (#000000), full-screen imagery, and fluid horizontal navigation.' => 'Խոր սեւ լուսանկարչական մութ սենեակի մթնոլորտ (#000000), ամբողջ պաստառով պատկերներ եւ սահուն հորիզոնական նաւարկութիւն։',
    'Dark Black (#000000)' => 'Խոր սեւ (#000000)',
