    'Right Visual Spread' => 'Տեսողական բացուածք աջին',
    'Horizontal Classic Nav' => 'Դասական հորիզոնական նաւարկութիւն',
    'Pure White Cube Gallery' => 'Մաքուր ճերմակ White Cube պատկերասրահ',
    'Pure White & Minimal' => 'Մաքուր ճերմակ եւ նուազագոյն',
    'Modern contemporary gallery aesthetic in stark pure white (#FFFFFF), preserving original aspect ratios in white cube spreads with dark typography.' => 'Արդի պատկերասրահի գեղագիտութիւն մաքուր ճերմակով (#FFFFFF)՝ պահելով բնօրինակ համեմատութիւնները white cube բացուածքներուն մէջ՝ մութ գրատեսակով։',
    'Pure White (#FFFFFF)' => 'Մաքուր ճերմակ (#FFFFFF)',
    'White Cube Gallery' => 'White Cube պատկերասրահ',
    'White Cube Exhibition' => 'White Cube ցուցադրութիւն',
    'Horizontal Left Menu' => 'Հորիզոնական մենիւ ձախին',
    'Editorial Magazine & Essay' => 'Խմբագրական հանդէս եւ յօդուած',
    'Editorial' => 'Խմբագրական',
    'Strong typographic hierarchy, large covers, two-column magazine spreads, and narrative photo-essay rhythm.' => 'Ուժեղ տպագրական աստիճանակարգ, մեծ կողքեր, երկսիւն հանդէսի բացուածքներ եւ լուսանկարչական յօդուածի պատումային կշռոյթ։',
    'Dark Charcoal (#0A0C10)' => 'Մութ ածխագոյն (#0A0C10)',
    'Editorial Magazine Cover' => 'Խմբագրական հանդէսի կողք',
    'Magazine Article Spread' => 'Հանդէսի յօդուածի բացուածք',
    'Museum Paper & Passepartout' => 'Թանգարանային թուղթ եւ պասպարտու',
    'Art Book Texture' => 'Արուեստի գիրքի հիւսուածք',
    'Warm archival cream paper (#F4F2ED), symmetric passepartout borders, and curatorial exhibition labels.' => 'Տաք սերուցքագոյն արխիւային թուղթ (#F4F2ED), համաչափ պասպարտուի լուսանցքներ եւ համադրողական ցուցահանդէսային պիտակներ։',
    'Warm Cream Paper (#F4F2ED)' => 'Տաք սերուցքագոյն թուղթ (#F4F2ED)',
    'Centered Museum Spread' => 'Կեդրոնացուած թանգարանային բացուածք',
    'Contemporary Vertical Monograph' => 'Արդի ուղղահայեաց մենագրութիւն',
    'Monograph' => 'Մենագրութիւն',
    'Fixed left vertical sidebar navigation, monograph chapters, and continuous visual exhibition wall.' => 'Հաստատուն ուղղահայեաց կողային նաւարկութիւն ձախին, մենագրութեան գլուխներ եւ անընդհատ տեսողական ցուցադրութեան պատ։',
    'Vertical Story Chapters' => 'Պատմութեան ուղղահայեաց գլուխներ',
    'Sticky Split Monograph' => 'Հաստատուն բաժանուած մենագրութիւն',
    'Left Vertical Menu' => 'Ուղղահայեաց մենիւ ձախին',
    'Sidebar List' => 'Կողային վահանակի ցանկ',
    'New · Minimal' => 'Նոր · Նուազագոյն',
    'White background, project list on the left and one large uncropped photo on the right; captioned sequence on project pages. For a few strong projects.' => 'Ճերմակ ետնանկար, նախագիծերու ցանկ ձախին եւ մէկ մեծ չկտրուած լուսանկար աջին. նախագիծի էջերուն մէջ՝ մակագրուած յաջորդականութիւն։ Քանի մը ուժեղ նախագիծերու համար։',
    'White' => 'Ճերմակ',
    'Captioned Sequence' => 'Մակագրուած յաջորդականութիւն',
    'Left-Aligned Top Bar' => 'Ձախ հաւասարեցուած վերի տող',
    'Map Atlas' => 'Քարտէզներու ատլաս',
    'New · Documentary' => 'Նոր · Վաւերագրական',
    'Projects on a world map on the homepage, archive by year in the portfolio, captioned sequence on project pages. For work across many places.' => 'Նախագիծեր աշխարհի քարտէզին վրայ՝ գլխաւոր էջին մէջ, արխիւ ըստ տարիներու՝ պորտֆոլիոյին մէջ, մակագրուած յաջորդականութիւն՝ նախագիծի էջերուն մէջ։ Բազմաթիւ վայրերու մէջ կատարուած աշխատանքի համար։',
    'Dark' => 'Մութ',
    'Project Map' => 'Նախագիծերու քարտէզ',
    'Classic Top Bar' => 'Դասական վերի տող',
    'Archive' => 'Արխիւ',
    'New · Archive' => 'Նոր · Արխիւ',
    'Archive by year on the homepage, contact sheet in the portfolio, two-column gallery on project pages. For many projects over many years.' => 'Արխիւ ըստ տարիներու՝ գլխաւոր էջին մէջ, կապի թերթ՝ պորտֆոլիոյին մէջ, երկսիւն պատկերասրահ՝ նախագիծի էջերուն մէջ։ Երկար տարիներու բազմաթիւ նախագիծերու համար։',
    'Archive by Year' => 'Արխիւ ըստ տարիներու',
    'Two-Column Gallery' => 'Երկսիւն պատկերասրահ',
    'Photobook' => 'Լուսանկարագիրք',
    'New · Book' => 'Նոր · Գիրք',
    'Cream paper background; photo and short statement on the homepage, free collage in the portfolio, book-like spreads on project pages.' => 'Սերուցքագոյն թուղթի ետնանկար. լուսանկար եւ կարճ բնագիր՝ գլխաւոր էջին մէջ, ազատ կոլաժ՝ պորտֆոլիոյին մէջ, գիրքի նման բացուածքներ՝ նախագիծի էջերուն մէջ։',
    'Cream Paper' => 'Սերուցքագոյն թուղթ',
    'Photo + Statement' => 'Լուսանկար + բնագիր',
    'Photobook Spread' => 'Լուսանկարագիրքի բացուածք',
    'Agency Showcase' => 'Գործակալութեան ցուցափեղկ',
    'New · Showcase' => 'Նոր · Ցուցափեղկ',
    'Full-screen cover, selected work, latest writing and a contact call on the homepage; curatorial grid in the portfolio. Gives editors and clients a quick overview.' => 'Ամբողջ պաստառով կողք, ընտրուած գործեր, վերջին գրառումներ եւ կապի կոչ՝ գլխաւոր էջին մէջ. համադրողական ցանց՝ պորտֆոլիոյին մէջ։ Խմբագիրներուն եւ պատուիրատուներուն կու տայ արագ պատկերացում։',
    'Sectioned Showcase' => 'Բաժիններով ցուցափեղկ',
    'Cinematic Cover' => 'Շարժանկարային կողք',
    'Transparent Top Bar' => 'Թափանցիկ վերի տող',
    'Unpublished changes discarded.' => 'Չհրատարակուած փոփոխութիւնները ջնջուեցան։',
    'No changes to publish.' => 'Հրատարակելու փոփոխութիւններ չկան։',
    'Page design published; the rest of the site is unchanged. Use “Revert to previous look” to undo.' => 'Էջին ձեւաւորումը հրատարակուեցաւ. կայքին մնացեալ մասը անփոփոխ է։ Ետ առնելու համար գործածեցէք «Վերադառնալ նախորդ տեսքին»։',
    '“%s” theme published. Use “Revert to previous look” to undo.' => '«%s» կաղապարը հրատարակուեցաւ։ Ետ առնելու համար գործածեցէք «Վերադառնալ նախորդ տեսքին»։',
    'Security check failed (CSRF).' => 'Ապահովութեան ստուգումը ձախողեցաւ (CSRF)։',
    'Look before applying “%s”' => 'Դիտեցէք՝ «%s»-ը կիրարկելէ առաջ',
    '“%s” applied. Use “Revert to previous look” to undo.' => '«%s»-ը կիրարկուեցաւ։ Ետ առնելու համար գործածեցէք «Վերադառնալ նախորդ տեսքին»։',
    'Reverted to the previous look.' => 'Վերադարձուեցաւ նախորդ տեսքին։',
    'Template options saved.' => 'Կաղապարին ընտրանքները պահուեցան։',
    'Click a theme to see what it offers, preview it with your own photographs, customise its colours, logo and menu, and publish.' => 'Սեղմեցէք կաղապարի մը վրայ՝ տեսնելու, թէ ինչ կ՚առաջարկէ, նախադիտեցէք ձեր սեփական լուսանկարներով, յարմարեցուցէք գոյները, լոկօն եւ մենիւն ու հրատարակեցէք։',
    '“%s” is being previewed in your browser only; the site has not changed for visitors.' => '«%s»-ը կը նախադիտուի միայն ձեր զննարկիչին մէջ. այցելուներուն համար կայքը չէ փոխուած։',
    '“%s” was applied on %s. If you don’t like it, revert to the previous look in one click.' => '«%s»-ը կիրարկուած է %s-ին։ Եթէ չէք հաւնիր, մէկ սեղմումով վերադարձէք նախորդ տեսքին։',
    'Revert the site to the look it had before this template?' => 'Վերադարձնե՞լ կայքը այն տեսքին, որ ունէր այս կաղապարէն առաջ',
