    'The preview on the right uses your own photographs and is shown only to you. Visitors see no change until you press “Publish”.' => 'Աջին նախադիտումը կը գործածէ ձեր սեփական լուսանկարները եւ կը ցուցադրուի միայն ձեզի։ Այցելուները փոփոխութիւն չեն տեսներ, մինչեւ որ չսեղմէք «Հրատարակել»։',
    'Design editor' => 'Ձեւաւորման խմբագրիչ',
