    'Publish the changes? Shared settings apply site-wide; page settings apply only to: %s. You can revert in one click.' => 'Հրատարակե՞լ փոփոխութիւնները։ Ընդհանուր կարգաւորումները կը կիրարկուին ամբողջ կայքին վրայ, էջի կարգաւորումները՝ միայն՝ %s։ Կրնաք վերադարձնել մէկ սեղմումով։',
    'Publish the “%s” theme with these settings to the whole site? You can revert in one click.' => 'Հրատարակե՞լ «%s» կաղապարը այս կարգաւորումներով ամբողջ կայքին վրայ։ Կրնաք վերադարձնել մէկ սեղմումով։',
    'Discard all unpublished changes?' => 'Ջնջե՞լ բոլոր չհրատարակուած փոփոխութիւնները',
