    'Every colour on your site, section by section. A colour set here overrides the basic colours.' => 'Ձեր կայքին իւրաքանչիւր գոյնը՝ բաժին առ բաժին։ Հոս սահմանուած գոյնը կը փոխարինէ հիմնական գոյները։',
    'Every text setting on your site, section by section.' => 'Ձեր կայքին իւրաքանչիւր բնագրային կարգաւորումը՝ բաժին առ բաժին։',
    'Change the main colours of your site quickly, in one place.' => 'Արագ փոխեցէք ձեր կայքին հիմնական գոյները՝ մէկ տեղէն։',
    'Change all the fonts on your site quickly, in one place.' => 'Արագ փոխեցէք ձեր կայքին բոլոր գրատեսակները՝ մէկ տեղէն։',
