    'This tone is too dark. Pick a light tone, or use “Black” for a dark site.' => 'Այս երանգը չափազանց մութ է։ Ընտրեցէք բաց երանգ կամ մութ կայքի համար գործածեցէք «Սեւ»-ը։',
    'Which page' => 'Ո՛ր էջը',
    'All lists (shared)' => 'Բոլոր ցանկերը (ընդհանուր)',
    'All project pages (shared)' => 'Նախագիծերու բոլոր էջերը (ընդհանուր)',
    'own settings' => 'սեփական կարգաւորումներ',
    'Settings here apply to every page that has no settings of its own.' => 'Հոսկէ կարգաւորումները կը կիրարկուին իւրաքանչիւր էջի համար, որ սեփական կարգաւորումներ չունի։',
    'This page uses the shared settings. To give it its own layout and settings:' => 'Այս էջը կը գործածէ ընդհանուր կարգաւորումները։ Անոր սեփական դասաւորութիւն եւ կարգաւորումներ տալու համար՝',
    'Give this page its own settings' => 'Այս էջին տալ սեփական կարգաւորումներ',
    'This page has its own settings; changes to the shared settings do not affect it.' => 'Այս էջը ունի սեփական կարգաւորումներ. ընդհանուր կարգաւորումներու փոփոխութիւնները անոր վրայ չեն ազդեր։',
    'Use shared settings' => 'Գործածել ընդհանուր կարգաւորումները',
    '%s: every project in the list' => '%s՝ ցանկին իւրաքանչիւր նախագիծը',
    'Show all design settings' => 'Ցուցադրել ձեւաւորման բոլոր կարգաւորումները',
    'Colours, fonts, menu and other pages' => 'Գոյներ, գրատեսակներ, մենիւ եւ այլ էջեր',
    'The change could not be saved. Check your connection and try again.' => 'Փոփոխութիւնը չյաջողեցաւ պահել։ Ստուգեցէք կապը եւ կրկին փորձեցէք։',
