    'Section pages' => 'Բաժիններու էջեր',
    '13. Sidebar List' => '13. Կողային վահանակի ցանկ',
    'Numbered project list on the left, one large uncropped photo on the right; hovering the list switches the photo. Best for a few strong projects.' => 'Նախագիծերու համարակալուած ցանկ ձախին, մէկ մեծ չկտրուած լուսանկար աջին. ցանկին վրայ ցուցիչը պահելու ատեն լուսանկարը կը փոխուի։ Լաւագոյնն է քանի մը ուժեղ նախագիծերու համար։',
    '14. Archive by Year' => '14. Արխիւ ըստ տարիներու',
    'Projects grouped under year headings with thumbnail, title and place. Best for a long, multi-project archive.' => 'Նախագիծերը խմբաւորուած են տարիներու խորագիրներուն տակ՝ մանրապատկերով, խորագիրով եւ վայրով։ Լաւագոյնն է բազմաթիւ նախագիծերով երկար արխիւի համար։',
    '15. Contact Sheet' => '15. Կապի թերթ',
    'All works as small numbered frames on black, like a film contact sheet; frames enlarge on hover. Best for many works.' => 'Բոլոր գործերը՝ որպէս պզտիկ համարակալուած կադրեր սեւին վրայ, ինչպէս ժապաւէնի կապի թերթ. ցուցիչը պահելու ատեն կադրերը կը մեծնան։ Լաւագոյնն է շատ գործերու համար։',
    '16. Photo + Statement' => '16. Լուսանկար + բնագիր',
    'One large photo on one side, a short statement in large type and the project list on the other. The text comes from the site description in Site Settings › General.' => 'Մէկ կողմը՝ մէկ մեծ լուսանկար, միւսը՝ կարճ բնագիր մեծ տառերով եւ նախագիծերու ցանկը։ Բնագիրը կ՚առնուի կայքին նկարագրութենէն՝ Կայքին կարգաւորումներ › Ընդհանուր բաժինէն։',
    '17. Project Map' => '17. Նախագիծերու քարտէզ',
    'Each project as a point on a world map where it was shot; clicking shows the cover and link. Project list alongside. Places are found from each project’s Location field.' => 'Իւրաքանչիւր նախագիծ՝ որպէս կէտ աշխարհի քարտէզին վրայ՝ նկարահանման վայրին մէջ. սեղմելու ատեն կը ցուցադրուին կողքը եւ յղումը։ Կողքին՝ նախագիծերու ցանկը։ Վայրերը կ՚որոշուին իւրաքանչիւր նախագիծի Վայր դաշտէն։',
    '18. Sectioned Showcase' => '18. Բաժիններով ցուցափեղկ',
    'Full-screen cover, then Selected Work cards, latest blog posts (if blog is on), a short intro and About / Contact links. Everything on one page.' => 'Ամբողջ պաստառով կողք, ապա ընտրուած գործերու քարտեր, բլոգի վերջին գրառումները (եթէ բլոգը միացուած է), կարճ ներածութիւն եւ Իմ մասին / Կապ յղումներ։ Ամէն ինչ մէկ էջի մէջ։',
    '20. Thumbnail Grid' => '20. Մանրապատկերներու ցանց',
    'All work as small thumbnails side by side; titles on hover. Looks best with the sidebar menu. Columns and cropping are chosen on the Templates page.' => 'Բոլոր գործերը՝ որպէս պզտիկ մանրապատկերներ կողք կողքի. խորագիրները՝ ցուցիչը պահելու ատեն։ Լաւագոյնս կ՚երեւի կողային մենիւի հետ։ Սիւնակները եւ կտրումը կ՚ընտրուին Կաղապարներ էջին մէջ։',
    '21. Photobook Spreads' => '21. Լուսանկարագիրքի բացուածքներ',
    'Work laid out as two-page book spreads on warm paper; the first page shows the site name and description. Page by page on phones.' => 'Գործերը դասաւորուած են որպէս երկէջանի գիրքի բացուածքներ տաք թուղթի վրայ. առաջին էջին մէջ՝ կայքին անունը եւ նկարագրութիւնը։ Հեռաձայններուն մէջ՝ էջ առ էջ։',
    '22. Mosaic Wall' => '22. Խճանկարային պատ',
    'Covers of varying sizes form a dense wall; titles on hover. Columns are chosen on the Templates page.' => 'Տարբեր չափերու կողքերը կը կազմեն խիտ պատ. խորագիրները՝ ցուցիչը պահելու ատեն։ Սիւնակները կ՚ընտրուին Կաղապարներ էջին մէջ։',
    '23. Photo Wall' => '23. Լուսանկարներու պատ',
    'Photos stacked uncropped in columns at their natural proportions, titles below. Set the column count in Themes › Customise › Homepage. Best for: series that mix portrait and landscape photos.' => 'Լուսանկարները՝ չկտրուած, սիւնակներով՝ իրենց բնական համեմատութիւններով, խորագիրները՝ վարը։ Սիւնակներու քանակը սահմանեցէք Կաղապարներ › Յարմարեցնել › Գլխաւոր էջ բաժինին մէջ։ Լաւագոյնն է՝ ուղղահայեաց եւ հորիզոնական լուսանկարներ համադրող շարքերու համար։',
    '24. Staggered Gallery' => '24. Շեղուած պատկերասրահ',
    'Uncropped photos in varying widths and offsets with generous space. Best for: calm selections that should feel like a gallery wall.' => 'Չկտրուած լուսանկարներ՝ տարբեր լայնքերով եւ շեղումներով, առատ տարածութեամբ։ Լաւագոյնն է՝ հանդարտ ընտրանիներու համար, որոնք պէտք է յիշեցնեն պատկերասրահի պատ։',
    '25. One Large, Two Small' => '25. Մէկ մեծ, երկու պզտիկ',
    'Blocks of three: one large and two small photos, the large one alternating sides. Best for: projects with strong cover photos.' => 'Եռեակներ՝ մէկ մեծ եւ երկու պզտիկ լուսանկար, մեծը հերթով կողմը կը փոխէ։ Լաւագոյնն է՝ ուժեղ կողքի լուսանկարներ ունեցող նախագիծերու համար։',
    '26. Featured + Grid' => '26. Առանձնացուած + ցանց',
    'The first work large and uncropped, then small square thumbnails. Best for: when you want to lead with one recent work.' => 'Առաջին գործը՝ մեծ եւ չկտրուած, ապա պզտիկ քառակուսի մանրապատկերներ։ Լաւագոյնն է՝ երբ կ՚ուզէք սկսիլ վերջին գործերէն մէկով։',
    '27. Zigzag Stream' => '27. Զիկզակ հոսք',
    'Uncropped photos flow down the page, alternating left and right, titles below. Best for: strong single frames worth a long look.' => 'Չկտրուած լուսանկարները կը հոսին էջէն վար՝ հերթով ձախ եւ աջ, խորագիրները՝ վարը։ Լաւագոյնն է՝ ուժեղ առանձին կադրերու համար, որոնք արժանի են երկար ակնարկի։',
    '28. Split Screens' => '28. Բաժնուած պաստառներ',
    'Each project fills a screen: photo on one half, title and short text on the other, sides alternating. Choose edge-to-edge or framed (magazine) style.' => 'Իւրաքանչիւր նախագիծ կը գրաւէ մէկ պաստառ՝ մէկ կէսին մէջ լուսանկար, միւսին մէջ՝ խորագիր եւ կարճ բնագիր, կողմերը կը հերթափոխուին։ Ընտրեցէք եզրէն եզր կամ շրջանակով (հանդէսի) ոճը։',
    '29. Three Panels' => '29. Երեք վահանակ',
    'The screen splits into three tall panels, each a project cover with its name centred. Stacked on phones. Best for: portfolios with three to six main projects.' => 'Պաստառը կը բաժնուի երեք բարձր վահանակի, իւրաքանչիւրը՝ նախագիծի կողք՝ անունը կեդրոնը։ Հեռաձայններուն մէջ՝ մէկը միւսին տակ։ Լաւագոյնն է՝ երեքէն վեց հիմնական նախագիծ ունեցող պորտֆոլիոներու համար։',
    '30. Section Banners' => '30. Բաժիններու ազդագօտիներ',
    'Each menu section becomes a wide banner with a cover photo, large title and an arrow. Shows sections on the homepage and projects on project lists.' => 'Մենիւի իւրաքանչիւր բաժին կը դառնայ լայն ազդագօտի՝ կողքի լուսանկարով, մեծ խորագիրով եւ սլաքով։ Գլխաւոր էջին մէջ կը ցուցադրէ բաժինները, նախագիծերու ցանկերուն մէջ՝ նախագիծերը։',
    '31. Light Table' => '31. Լուսային սեղան',
    'One large photo with a vertical thumbnail strip on the right; click a thumbnail (or use the arrow keys) to change the photo. On phones the strip moves below. Best for: showing photos one at a time on a dark background.' => 'Մէկ մեծ լուսանկար՝ աջին մանրապատկերներու ուղղահայեաց ժապաւէնով. լուսանկարը փոխելու համար սեղմեցէք մանրապատկերի մը վրայ (կամ գործածեցէք սլաքի ստեղները)։ Հեռաձայններուն մէջ ժապաւէնը վար կը փոխադրուի։ Լաւագոյնն է՝ լուսանկարները մէկ առ մէկ մութ ետնանկարի վրայ ցուցադրելու համար։',
    '19. Free Collage' => '19. Ազատ կոլաժ',
    'Photos placed freely in varied sizes and positions without a grid; titles appear on hover. Single column on phones. For artistic and personal work.' => 'Լուսանկարները զետեղուած են ազատօրէն՝ տարբեր չափերով եւ դիրքերով, առանց ցանցի. խորագիրները կը յայտնուին ցուցիչը պահելու ատեն։ Հեռաձայններուն մէջ՝ մէկ սիւնակ։ Գեղարուեստական եւ անձնական գործերու համար։',
    'You have unsaved changes' => 'Ունիք չպահուած փոփոխութիւններ',
    'Discard' => 'Խափանել',
    'Unlisted' => 'Ցանկէն դուրս',
    'View on site' => 'Դիտել կայքին վրայ',
    'Save (Ctrl+S)' => 'Պահել (Ctrl+S)',
    'Homepage slide' => 'Գլխաւոր էջի սահիկ',
    'Site settings / design' => 'Կայքին կարգաւորումներ / ձեւաւորում',
    'CSRF security verification failed.' => 'CSRF ապահովութեան ստուգումը ձախողեցաւ։',
    'All page names, URL slugs, and top menu links have been updated.' => 'Բոլոր էջերուն անունները, URL slug-երը եւ վերի մենիւի յղումները թարմացուեցան։',
    'Customize page names and permalinks. Changes automatically sync across panel templates, sidebars, and public navigation.' => 'Յարմարեցուցէք էջերուն անունները եւ մնայուն յղումները։ Փոփոխութիւնները ինքնաբերաբար կը համաժամացուին վահանակին կաղապարներուն, կողային վահանակներուն եւ հանրային նաւարկութեան մէջ։',
    'Select Language to Edit:' => 'Ընտրեցէք խմբագրման լեզուն՝',
    '1. Portfolio Main Name & Categories' => '1. Պորտֆոլիոյի հիմնական անուն եւ դասակարգեր',
    'Changing the Portfolio main name will automatically update all templates and panel sidebar links.' => 'Պորտֆոլիոյի հիմնական անունը փոխելու ատեն բոլոր կաղապարները եւ վահանակին կողային յղումները ինքնաբերաբար կը թարմացուին։',
    'Portfolio Manager →' => 'Պորտֆոլիոյի կառավարում →',
    'Section / Category' => 'Բաժին / Դասակարգ',
    'Display Name (Menu & Title)' => 'Ցուցադրուող անուն (մենիւ եւ խորագիր)',
    'Page address' => 'Էջին հասցէն',
    'Portfolio Name in Admin Menu' => 'Պորտֆոլիոյի անունը վարիչի մենիւին մէջ',
    'Shown only in the admin sidebar' => 'Կը ցուցադրուի միայն վարիչի կողային վահանակին մէջ',
    'Not shown on the site' => 'Չի ցուցադրուիր կայքին մէջ',
    '2. Static Pages (Blog, About, Contact etc.)' => '2. Ստատիկ էջեր (Բլոգ, Իմ մասին, Կապ եւ այլն)',
    'Rename pages to anything you like. The top menu updates automatically.' => 'Վերանուանեցէք էջերը ինչպէս որ կ՚ուզէք։ Վերի մենիւն ինքնաբերաբար կը թարմացուի։',
    'Page Type' => 'Էջին տեսակը',
    'Homepage Root' => 'Գլխաւոր էջի արմատ',
    'Image Converter' => 'Պատկերներու փոխարկիչ',
    'Generates fast-loading AVIF and WebP versions and smaller sizes of uploaded photos.' => 'Կը ստեղծէ վերբեռնուած լուսանկարներուն արագ բեռնուող AVIF եւ WebP տարբերակները եւ աւելի պզտիկ չափեր։',
    'High Depth & Engagement' => 'Բարձր խորութիւն եւ ներգրաւուածութիւն',
    'Photo reading time' => 'Լուսանկարի դիտումի ժամանակ',
    'Portfolio & Stories' => 'Պորտֆոլիո եւ պատմութիւններ',
    'Per user' => 'Մէկ գործածողի հաշուով',
    'Unique visits' => 'Եզակի այցելութիւններ',
    'Desktop (Editorial / Jury)' => 'Համակարգիչ (խմբագրական / դատական կազմ)',
    'Avg.' => 'Միջ.',
