    'New article' => 'Նոր յօդուած',
    'Shown when an address is not found. Write the title and text in each language; if you set it to draft, the default text is shown.' => 'Կը ցուցադրուի, երբ հասցէն չի գտնուիր։ Գրեցէք խորագիրը եւ բնագիրը իւրաքանչիւր լեզուով. եթէ զայն սեւագիր դարձնէք, կը ցուցադրուի նախնական բնագիրը։',
    'Write a title and build the content in the editor below. The page appears at its own address as a simple text page.' => 'Գրեցէք խորագիր եւ կառուցեցէք բովանդակութիւնը ստորեւ բերուած խմբագրիչին մէջ։ Էջը կը յայտնուի իր սեփական հասցէով՝ որպէս պարզ բնագրային էջ։',
    'Publish your essay, field note or news in several languages.' => 'Հրատարակեցէք ձեր յօդուածը, դաշտային նշումը կամ լուրը քանի մը լեզուով։',
