    'Pick one of the theme\'s About, Contact or project page layouts. The cover image is used as the portrait or page photo; colours and other options follow that page in Themes › Customize.' => 'Ընտրեցէք կաղապարին Իմ մասին, Կապ կամ նախագիծի էջի դասաւորութիւններէն մէկը։ Կողքի պատկերը կը գործածուի որպէս դիմանկար կամ էջի լուսանկար. գոյները եւ այլ ընտրանքները կը հետեւին այդ էջին՝ Կաղապարներ › Յարմարեցնել բաժինին մէջ։',
