    'Language:' => 'Լեզու՝',
    'Copy empty fields and photo captions from source language (TR/EN)' => 'Պատճէնել պարապ դաշտերը եւ լուսանկարներու մակագրութիւնները աղբիւր լեզուէն (TR/EN)',
