    'Fields containing MYMEMORY WARNING found in this language. You can clear them with one click.' => 'Այս լեզուին մէջ յայտնաբերուեցան MYMEMORY WARNING պարունակող դաշտեր։ Կրնաք մաքրել զանոնք մէկ սեղմումով։',
    'Clear Error Warnings Now' => 'Մաքրել սխալի զգուշացումները հիմա',
    'Short Description' => 'Կարճ նկարագրութիւն',
    'Location / Geography' => 'Վայր / աշխարհագրութիւն',
