    'Your own light tone instead of white, paper or gray. Dark tones are not accepted; choose “Black” for a dark site.' => 'Ձեր սեփական բաց երանգը՝ ճերմակի, թուղթի կամ մոխրագոյնի փոխարէն։ Մութ երանգներ չեն ընդունուիր. մութ կայքի համար ընտրեցէք «Սեւ»։',
    'Text colour' => 'Բնագիրի գոյն',
    'Colour of headings, paragraphs and lists. Text over photographs is unchanged. Returns to automatic if a visitor switches light/dark.' => 'Խորագիրներու, պարբերութիւններու եւ ցանկերու գոյնը։ Լուսանկարներուն վրայի բնագիրը չի փոխուիր։ Կը վերադառնայ ինքնաշխատին, եթէ այցելուն փոխէ բաց/մութ կերպը։',
