    'Heading font' => 'Խորագիրներու գրատեսակ',
    'Project names, page titles and large text.' => 'Նախագիծերու անուններ, էջերու խորագիրներ եւ մեծ բնագիր։',
    'Body font' => 'Հիմնական բնագիրի գրատեսակ',
