    'Base font size' => 'Հիմնական տառաչափ',
    'Scales all text on the site proportionally.' => 'Համեմատաբար կը մեծցնէ կամ կը պզտիկցնէ կայքին ամբողջ բնագիրը։',
    'Button corners' => 'Կոճակներու անկիւններ',
