    'Form fields' => 'Ձեւաթուղթի դաշտեր',
    'How the contact form and password field look. Corners match the buttons.' => 'Ինչպէս կ՚երեւին կապի ձեւաթուղթը եւ գաղտնաբառի դաշտը։ Անկիւնները կը համընկնին կոճակներուն հետ։',
    'What appears top left' => 'Ինչ կ՚երեւի վերը ձախին',
    'Text (your name), your uploaded logo image, or both.' => 'Բնագիր (ձեր անունը), ձեր վերբեռնած լոկօի պատկերը կամ երկուքը միասին։',
