    'Height of the symbol or full logo image.' => 'Խորհրդանիշին կամ ամբողջական լոկօի պատկերին բարձրութիւնը։',
    'Symbol · on dark backgrounds' => 'Խորհրդանիշ · մութ ետնանկարի վրայ',
