    'Logo and text are shown at this scale on phones.' => 'Հեռաձայններուն մէջ լոկօն եւ բնագիրը կը ցուցադրուին այս չափով։',
    'Browser tab icon' => 'Զննարկիչի ներդիրի պատկերակ',
    'Shown in browser tabs and bookmarks. A square PNG or ICO is best.' => 'Կը ցուցադրուի զննարկիչի ներդիրներուն եւ էջանիշներուն մէջ։ Լաւագոյնը քառակուսի PNG կամ ICO է։',
    'Menu bar on the homepage' => 'Մենիւի տողը գլխաւոր էջին մէջ',
