    'Top' => 'Վերը',
    'Bottom' => 'Վարը',
    'Menu width' => 'Մենիւի լայնք',
    'Full: edge to edge. Contained and Narrow: centred to the content width.' => 'Ամբողջական՝ եզրէն եզր։ Սահմանափակ եւ Նեղ՝ կեդրոնացուած բովանդակութեան լայնքով։',
    'Full' => 'Ամբողջական',
    'Contained' => 'Սահմանափակ',
    'Narrow' => 'Նեղ',
    'When the page scrolls' => 'Երբ էջը կը սահի',
    'How the menu behaves on inner pages. “On scroll up”: hides going down, reappears going up.' => 'Ինչպէս մենիւն կը վարուի ներքին էջերուն մէջ։ «Վեր սահելու ատեն»՝ կը պահուի վար սահելու ատեն եւ կրկին կը յայտնուի վեր սահելու ատեն։',
    'Scrolls away' => 'Կը սահի էջին հետ',
    'Stays fixed' => 'Կը մնայ հաստատուն',
    'On scroll up' => 'Վեր սահելու ատեն',
    'Menu background on scroll' => 'Մենիւի ետնանկարը սահելու ատեն',
    'Frosted' => 'Աղօտ ապակի',
    'Solid' => 'Միագոյն',
    'Menu on full-screen photo pages' => 'Մենիւն ամբողջ պաստառով լուսանկար ունեցող էջերուն մէջ',
    'On pages where the photo fills the screen, such as the homepage and section covers.' => 'Այն էջերուն մէջ, ուր լուսանկարը կը լեցնէ պաստառը, օրինակ՝ գլխաւոր էջին եւ բաժիններու կողքերուն մէջ։',
