    'Cards: equal boxes with the title over the photo. Uncropped: natural proportions with the title below. Full height: screen-tall with no gaps.' => 'Քարտեր՝ հաւասար տուփեր, խորագիրը լուսանկարին վրայ։ Չկտրուած՝ բնական համեմատութիւններ, խորագիրը վարը։ Ամբողջ բարձրութեամբ՝ պաստառին բարձրութեամբ, առանց բացատներու։',
    'Intro text above' => 'Ներածական բնագիր վերը',
    'The site description from Site Settings is shown in large type above the photos. Write **word** to make a word bold.' => 'Կայքին կարգաւորումներէն կայքին նկարագրութիւնը կը ցուցադրուի մեծ տառերով լուսանկարներուն վերեւը։ Բառը թաւ դարձնելու համար գրեցէք **բառ**։',
    'Split screen style' => 'Բաժնուած պաստառի ոճ',
