    'Leading with one recent work' => 'Սկսիլ վերջին գործերէն մէկով',
    'A “Menu” button top right' => '«Մենիւ» կոճակ վերը աջին',
    'A large intro sentence above two columns of photos' => 'Մեծ ներածական նախադասութիւն երկու սիւնակ լուսանկարներուն վերեւը',
    'A photo wall with titles' => 'Լուսանկարներու պատ՝ խորագիրներով',
    'Title, photo and text, then a photo wall' => 'Խորագիր, լուսանկար եւ բնագիր, ապա լուսանկարներու պատ',
    'Saying who you are in one sentence' => 'Մէկ նախադասութեամբ ըսել, թէ ո՛վ էք',
    'A lines button top right that opens the menu' => 'Գիծերով կոճակ վերը աջին, որ կը բանայ մենիւն',
    'Uncropped photos, alternating left and right' => 'Չկտրուած լուսանկարներ՝ հերթով ձախ եւ աջ',
    'The same zigzag stream' => 'Նոյն զիկզակ հոսքը',
    'A plain gallery-wall opening, then photos one by one' => 'Պարզ պատկերասրահային պատի բացում, ապա լուսանկարներ մէկ առ մէկ',
    'Strong single frames worth a long look' => 'Ուժեղ առանձին կադրեր, որոնք արժանի են երկար ակնարկի',
    'One screen per project: half photo, half text' => 'Մէկ պաստառ իւրաքանչիւր նախագիծի համար՝ կէսը լուսանկար, կէսը բնագիր',
    'The same split screens' => 'Նոյն բաժնուած պաստառները',
    'Photo left, text right, then photos one by one' => 'Լուսանկարը ձախին, բնագիրը աջին, ապա լուսանկարներ մէկ առ մէկ',
    'Introducing each project in a few sentences' => 'Իւրաքանչիւր նախագիծ քանի մը նախադասութեամբ ներկայացնելու համար',
    'A lines button top right' => 'Գիծերով կոճակ վերը աջին',
    'Magazine pages: a framed photo and a light title' => 'Հանդէսի էջեր՝ շրջանակուած լուսանկար եւ թեթեւ խորագիր',
    'The same magazine pages' => 'Նոյն հանդէսի էջերը',
    'Three tall project panels across the screen' => 'Նախագիծերու երեք բարձր վահանակ պաստառին ամբողջ լայնքով',
    'The same panels in rows of three' => 'Նոյն վահանակները՝ երեքական շարքերով',
    'A full-screen opening, then a captioned sequence' => 'Ամբողջ պաստառով բացում, ապա մակագրուած յաջորդականութիւն',
    'Portfolios with three to six main projects' => 'Երեքէն վեց հիմնական նախագիծ ունեցող պորտֆոլիոներ',
    'A wide banner for each menu section' => 'Լայն ազդագօտի մենիւի իւրաքանչիւր բաժինին համար',
    'Projects as banners, one below another' => 'Նախագիծեր՝ որպէս ազդագօտիներ, մէկը միւսին տակ',
    'Work organised into a few main sections' => 'Քանի մը հիմնական բաժիններու բաժնուած գործ',
    'One large photo with a thumbnail strip on the right' => 'Մէկ մեծ լուսանկար՝ աջին մանրապատկերներու ժապաւէնով',
    'The same light table with project covers' => 'Նոյն լուսային սեղանը՝ նախագիծերու կողքերով',
    'A full-screen opening, then a gallery wall' => 'Ամբողջ պաստառով բացում, ապա պատկերասրահային պատ',
    'Showing photos one at a time on a dark background' => 'Լուսանկարները մէկ առ մէկ մութ ետնանկարի վրայ ցուցադրելու համար',
    'Bottom right on the homepage, top on inner pages' => 'Գլխաւոր էջին մէջ՝ վարը աջին, ներքին էջերուն մէջ՝ վերը',
    'A fullscreen slideshow without captions' => 'Ամբողջ պաստառով սահիկներու ցուցադրութիւն՝ առանց մակագրութիւններու',
    'A full-screen opening, then photos one by one' => 'Ամբողջ պաստառով բացում, ապա լուսանկարներ մէկ առ մէկ',
    'Letting the photo fill the screen uninterrupted' => 'Թոյլ տալ լուսանկարին անխափան լեցնել պաստառը',
    'Sidebar + Thumbnail Grid' => 'Կողային վահանակ + մանրապատկերներու ցանց',
    'Fixed name and menu on the left; all work as small thumbnails side by side.' => 'Հաստատուն անուն եւ մենիւ ձախին. բոլոր գործերը՝ պզտիկ մանրապատկերներով կողք կողքի։',
    'Sidebar + Single Image' => 'Կողային վահանակ + մէկ պատկեր',
    'Name and menu on the left; one large uncropped image on a plain background.' => 'Անունը եւ մենիւն ձախին. մէկ մեծ, չկտրուած պատկեր՝ պարզ ետնանկարի վրայ։',
    'Top Menu + Fullscreen Slideshow' => 'Վերի մենիւ + ամբողջ պաստառով սահիկներու ցուցադրութիւն',
    'Menu over the image; one fullscreen photo per screen with its title.' => 'Մենիւն պատկերին վրայ. մէկ պաստառի վրայ՝ մէկ ամբողջ պաստառով լուսանկար՝ իր խորագիրով։',
    'Tiled Grid' => 'Սալիկային ցանց',
    'Project covers in equal tiles under a top menu; titles on hover.' => 'Նախագիծերու կողքեր հաւասար սալիկներով՝ վերի մենիւին տակ. խորագիրները՝ ցուցիչը պահելու ատեն։',
    'Horizontal Strip' => 'Հորիզոնական ժապաւէն',
    'Uncropped images at equal height in a sideways-scrolling row.' => 'Չկտրուած պատկերներ հաւասար բարձրութեամբ՝ կողային սահող շարքի մէջ։',
    'Vertical Stream' => 'Ուղղահայեաց հոսք',
    'Large images flowing down the page with titles and short text between them.' => 'Մեծ պատկերներ էջէն վար՝ անոնց միջեւ խորագիրներով եւ կարճ բնագիրով։',
    'Text Index' => 'Բնագրային ցանկ',
    'A large name and a project list; a small preview appears on hover.' => 'Մեծ անուն եւ նախագիծերու ցանկ. ցուցիչը պահելու ատեն կը յայտնուի պզտիկ նախադիտում։',
    'Mosaic Wall' => 'Խճանկարային պատ',
    'Covers of varying sizes form a dense wall; titles on hover.' => 'Տարբեր չափերու կողքերը կը կազմեն խիտ պատ. խորագիրները՝ ցուցիչը պահելու ատեն։',
    'Projects grouped under year headings with a small cover, title and place.' => 'Նախագիծերը խմբաւորուած են տարիներու խորագիրներուն տակ՝ պզտիկ կողքով, խորագիրով եւ վայրով։',
    'Warm paper background; projects laid out as two-page book spreads.' => 'Տաք թուղթի ետնանկար. նախագիծերը դասաւորուած են երկէջանի գիրքի բացուածքներով։',
    'Top Menu + Square Grid' => 'Վերի մենիւ + քառակուսի ցանց',
    'Name on the left, menu on the right; all work below in a centred grid of equal square thumbnails.' => 'Անունը ձախին, մենիւն աջին. բոլոր գործերը վարը՝ հաւասար քառակուսի մանրապատկերներու կեդրոնացուած ցանցի մէջ։',
    'Sidebar + Horizontal Gallery' => 'Կողային վահանակ + հորիզոնական պատկերասրահ',
    'Vertical menu on the left; large photos scroll sideways with project names below.' => 'Ուղղահայեաց մենիւ ձախին. մեծ լուսանկարներ կողային սահումով՝ նախագիծերու անունները վարը։',
    'Dark Sidebar + Horizontal Strip' => 'Մութ կողային վահանակ + հորիզոնական ժապաւէն',
    'Dark background; vertical menu on the left, full-height photos scrolling sideways.' => 'Մութ ետնանկար. ուղղահայեաց մենիւ ձախին, ամբողջ բարձրութեամբ լուսանկարներ կողային սահումով։',
    'Sidebar + Horizontal Strip' => 'Կողային վահանակ + հորիզոնական ժապաւէն',
    'Light background; vertical menu on the left, photos in a plain sideways-scrolling strip.' => 'Բաց ետնանկար. ուղղահայեաց մենիւ ձախին, լուսանկարներ պարզ կողային սահող ժապաւէնով։',
    'Sidebar + Wall' => 'Կողային վահանակ + պատ',
    'Vertical menu on the left; photos of varying heights stacked uncropped in columns.' => 'Ուղղահայեաց մենիւ ձախին. տարբեր բարձրութիւններու լուսանկարներ՝ չկտրուած, սիւնակներով։',
    'Staggered Gallery' => 'Շեղուած պատկերասրահ',
    'Name and menu centred; uncropped photos in varying widths and offsets with generous space.' => 'Անունը եւ մենիւն կեդրոնը. չկտրուած լուսանկարներ տարբեր լայնքերով եւ շեղումներով՝ առատ տարածութեամբ։',
    'One Large, Two Small' => 'Մէկ մեծ, երկու պզտիկ',
    'Name and a “Menu” button on top; blocks of one large and two small photos, the large one alternating sides.' => 'Անունը եւ «Մենիւ» կոճակը վերը. բլոկներ՝ մէկ մեծ եւ երկու պզտիկ լուսանկարով, մեծը հերթով կողմը կը փոխէ։',
    'Sidebar + Featured' => 'Կողային վահանակ + առանձնացուած',
    'Vertical menu on the left; the latest work large and uncropped, the rest as small squares below.' => 'Ուղղահայեաց մենիւ ձախին. վերջին գործը մեծ եւ չկտրուած, մնացեալը՝ պզտիկ քառակուսիներով վարը։',
    'Statement + Wall' => 'Բնագիր + պատ',
    'Name and a “Menu” button on top; a large intro sentence, then uncropped photos in two columns.' => 'Անունը եւ «Մենիւ» կոճակը վերը. մեծ ներածական նախադասութիւն, ապա չկտրուած լուսանկարներ երկու սիւնակով։',
    'Zigzag Stream' => 'Զիկզակ հոսք',
    'Name and a lines menu button on top; uncropped photos flow down the page, alternating left and right.' => 'Անունը եւ գիծերով մենիւի կոճակը վերը. չկտրուած լուսանկարները կը հոսին էջէն վար՝ հերթով ձախ եւ աջ։',
    'Split Screen' => 'Բաժնուած պաստառ',
    'Each project fills a screen: an edge-to-edge photo on one half, a large title and short text on the other.' => 'Իւրաքանչիւր նախագիծ կը լեցնէ մէկ պաստառ՝ մէկ կէսին մէջ եզրէն եզր լուսանկար, միւսին մէջ՝ մեծ խորագիր եւ կարճ բնագիր։',
    'Magazine Stories' => 'Հանդէսի պատմութիւններ',
    'Magazine pages on paper: a framed photo on a tinted panel, a light title and text beside it.' => 'Հանդէսի էջեր թուղթի վրայ՝ շրջանակուած լուսանկար երանգաւորուած վահանակի վրայ, կողքին՝ թեթեւ խորագիր եւ բնագիր։',
    'Three Panels' => 'Երեք վահանակ',
    'On a dark background the screen splits into three tall panels, each a project cover with its name centred.' => 'Մութ ետնանկարի վրայ պաստառը կը բաժնուի երեք բարձր վահանակի, իւրաքանչիւրը՝ նախագիծի կողք՝ անունը կեդրոնը։',
    'Section Banners' => 'Բաժիններու ազդագօտիներ',
    'Name and a menu button on top; each menu section is a wide banner with a cover photo, large title and an arrow.' => 'Անունը եւ մենիւի կոճակը վերը. մենիւի իւրաքանչիւր բաժին լայն ազդագօտի է՝ կողքի լուսանկարով, մեծ խորագիրով եւ սլաքով։',
    'Light Table' => 'Լուսային սեղան',
    'One large photo on a dark background with a vertical thumbnail strip on the right; click a thumbnail to change the photo.' => 'Մէկ մեծ լուսանկար մութ ետնանկարի վրայ՝ աջին մանրապատկերներու ուղղահայեաց ժապաւէնով. լուսանկարը փոխելու համար սեղմեցէք մանրապատկերին։',
    'Fullscreen + Bottom Bar' => 'Ամբողջ պաստառ + վարի տող',
    'The photo fills the whole screen; on the homepage the name and menu sit in a thin bar at the bottom.' => 'Լուսանկարը կը լեցնէ ամբողջ պաստառը. գլխաւոր էջին մէջ անունը եւ մենիւն կը գտնուին վարի բարակ տողին մէջ։',
    'Background' => 'Ետնանկար',
    'Site identity' => 'Կայքին ինքնութիւնը',
    'Symbol + text' => 'Խորհրդանիշ + բնագիր',
    'Full logo' => 'Ամբողջական լոկօ',
    'Symbol only' => 'Միայն խորհրդանիշ',
    'Subtitle under the name' => 'Ենթախորագիր անունին տակ',
    'Menu layout' => 'Մենիւին դասաւորութիւնը',
    'Top, right' => 'Վերը, աջ',
    'Top, centred' => 'Վերը, կեդրոն',
    'Centred under the name' => 'Կեդրոնը՝ անունին տակ',
    'Top, left' => 'Վերը, ձախ',
    'Hamburger ☰' => 'Համպուրկըր ☰',
    'Left sidebar' => 'Ձախ կողային վահանակ',
    'Uppercase menu' => 'Մեծատառ մենիւ',
    'Grid columns' => 'Ցանցի սիւնակներ',
    'Wall columns' => 'Պատի սիւնակներ',
    'Thumbnails' => 'Մանրապատկերներ',
